begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public','content_versions','immutable content version storage exists');
select ok(not has_table_privilege('authenticated','public.content_versions','SELECT'),'no browser content read bypass');
select ok(not has_table_privilege('service_role','public.content_versions','UPDATE'),'service cannot rewrite content or attach artifacts');
insert into public.organizations(id,name,slug) values('a3200000-0000-4000-8000-000000000001','Content SQL fixture','content-sql-032');
insert into public.business_settings(organization_id,revision,settings) values('a3200000-0000-4000-8000-000000000001',1,'{"brandName":"Fixture","brandVoice":"Plain","allowedTopics":[],"forbiddenTopics":[],"timezone":"Asia/Ho_Chi_Minh","goalSelection":"auto","managerGoal":"","timingMode":"constrained","dailyCap":1,"windows":[{"start":"09:00","end":"17:00"}],"objective":"mixed"}');
insert into public.products(id,organization_id,source_url,canonical_url,name,in_stock,stock_quantity,price_vnd,quality) values('b3200000-0000-4000-8000-000000000001','a3200000-0000-4000-8000-000000000001','urn:fixture:032','urn:fixture:032','Keyboard',true,2,100000,'partial');
insert into public.campaigns(id,organization_id,title,objective,source_kind,source_ref,priority,source_snapshot,settings_snapshot,timezone) values('c3200000-0000-4000-8000-000000000001','a3200000-0000-4000-8000-000000000001','Content fixture','mixed','product','b3200000-0000-4000-8000-000000000001',true,'{}','{}','Asia/Ho_Chi_Minh');
insert into public.campaign_slots(id,campaign_id,ordinal) values('d3200000-0000-4000-8000-000000000001','c3200000-0000-4000-8000-000000000001',1);
create temp table content_document as select jsonb_build_object('schema','onevoice.content.v1','draft','{}'::jsonb,'evidence',public.read_content_evidence('a3200000-0000-4000-8000-000000000001','[{"key":"product","kind":"product","id":"b3200000-0000-4000-8000-000000000001","skuId":"b3200000-0000-4000-8000-000000000001"},{"key":"_settings","kind":"brand","id":"a3200000-0000-4000-8000-000000000001"}]'),'templates','[]'::jsonb,'fields','{}'::jsonb,'validation','{"status":"VALID","validator":"ov032-v1"}'::jsonb,'artifactHash',null,'contentHash',repeat('a',64)) as doc;
-- SQL tests exercise trusted validated-document transaction fencing; TypeScript
-- tests separately require full field claims before calling this service-only RPC.
create function pg_temp.save_content(rev integer default 0,request uuid default 'f3200000-0000-4000-8000-000000000001',id uuid default 'e3200000-0000-4000-8000-000000000001') returns jsonb language sql as $$select public.save_content_version('a3200000-0000-4000-8000-000000000001','d3200000-0000-4000-8000-000000000001',id,request,rev,(select doc from content_document))$$;
select lives_ok($$select pg_temp.save_content()$$,'validated service document persists');
select lives_ok($$select pg_temp.save_content()$$,'request replay returns same immutable version');
select is((select count(*) from public.content_versions where slot_id='d3200000-0000-4000-8000-000000000001'),1::bigint,'one version after replay');
select is((select content_revision from public.campaign_slots where id='d3200000-0000-4000-8000-000000000001'),1,'slot revision updated atomically');
select ok((select artifact_hash is null from public.content_versions where id='e3200000-0000-4000-8000-000000000001'),'no pretend artifact hash');
select throws_ok($$update public.content_versions set document='{}' where id='e3200000-0000-4000-8000-000000000001'$$,'55000',null,'old document immutable');
select throws_ok($$delete from public.content_versions where id='e3200000-0000-4000-8000-000000000001'$$,'55000',null,'old version cannot be deleted');
select throws_ok($$select pg_temp.save_content(0,gen_random_uuid(),gen_random_uuid())$$,'40001','CONTENT_CONFLICT','stale slot version rejects');
select lives_ok($$select public.check_content_version('a3200000-0000-4000-8000-000000000001','e3200000-0000-4000-8000-000000000001')$$,'fresh current check');
update public.products set price_vnd=200000 where id='b3200000-0000-4000-8000-000000000001';
select throws_ok($$select public.check_content_version('a3200000-0000-4000-8000-000000000001','e3200000-0000-4000-8000-000000000001')$$,'40001','CONTENT_SOURCE_STALE','same-version changed price invalidates current check');
select throws_ok($$select pg_temp.save_content(1,gen_random_uuid(),gen_random_uuid())$$,'40001','CONTENT_SOURCE_STALE','generation snapshot cannot silently refresh');
update public.products set price_vnd=100000 where id='b3200000-0000-4000-8000-000000000001';
select throws_ok($$select public.check_content_version('a3200000-0000-4000-8000-000000000002','e3200000-0000-4000-8000-000000000001')$$,'42501','CONTENT_FORBIDDEN','foreign organization cannot inspect');
create function pg_temp.reject_content_audit() returns trigger language plpgsql as $$begin raise exception 'fixture_audit_failure'; end$$;
create trigger content_audit_fixture before insert on public.audit_events for each row execute function pg_temp.reject_content_audit();
select throws_ok($$select pg_temp.save_content(1,gen_random_uuid(),gen_random_uuid())$$,'P0001','fixture_audit_failure','audit failure aborts entire write');
select is((select content_revision from public.campaign_slots where id='d3200000-0000-4000-8000-000000000001'),1,'slot rolled back with audit');
select is((select count(*) from public.content_versions where slot_id='d3200000-0000-4000-8000-000000000001'),1::bigint,'failed audit leaves no version');
drop trigger content_audit_fixture on public.audit_events;
update public.business_settings set revision=2 where organization_id='a3200000-0000-4000-8000-000000000001';
select throws_ok($$select public.check_content_version('a3200000-0000-4000-8000-000000000001','e3200000-0000-4000-8000-000000000001')$$,'40001','CONTENT_SOURCE_STALE','settings revision is mandatory even without branding claim');
update public.business_settings set revision=1 where organization_id='a3200000-0000-4000-8000-000000000001';
insert into public.products(id,organization_id,source_url,canonical_url,name,in_stock,stock_quantity,price_vnd,quality) values('b3200000-0000-4000-8000-000000000004','a3200000-0000-4000-8000-000000000001','urn:fixture:032other','urn:fixture:032other','Other',true,2,100000,'partial');
insert into public.promotions(id,organization_id,label,scope) values('b3200000-0000-4000-8000-000000000005','a3200000-0000-4000-8000-000000000001','Other program','products');
insert into public.product_promotions(product_id,promotion_id) values('b3200000-0000-4000-8000-000000000004','b3200000-0000-4000-8000-000000000005');
update content_document set doc=jsonb_set(doc,'{evidence}',doc->'evidence'||public.read_content_evidence('a3200000-0000-4000-8000-000000000001','[{"key":"unrelated","kind":"program","id":"b3200000-0000-4000-8000-000000000005"}]'));
select throws_ok($$select pg_temp.save_content(1,gen_random_uuid(),gen_random_uuid())$$,'42501','CONTENT_FORBIDDEN','valid unrelated program cannot fulfill product campaign');
update content_document set doc=jsonb_set(doc,'{evidence}',(doc->'evidence')-2);
insert into public.product_variants(id,product_id,name,in_stock,stock_quantity,price_vnd) values('b3200000-0000-4000-8000-000000000002','b3200000-0000-4000-8000-000000000001','Variant',true,2,100000);
select throws_ok($$select public.check_content_version('a3200000-0000-4000-8000-000000000001','e3200000-0000-4000-8000-000000000001')$$,'40001','CONTENT_SOURCE_STALE','parent SKU invalid once variants exist');
insert into public.promotions(id,organization_id,label,scope,expires_at) values('b3200000-0000-4000-8000-000000000003','a3200000-0000-4000-8000-000000000001','Expired','all',clock_timestamp()-interval '1 second');
select throws_ok($$select public.read_content_evidence('a3200000-0000-4000-8000-000000000001','[{"key":"program","kind":"program","id":"b3200000-0000-4000-8000-000000000003"}]')$$,'22023','CAMPAIGN_SOURCE_INVALID','expired promotion excluded');
select throws_ok($$select public.read_content_evidence('a3200000-0000-4000-8000-000000000001','[{"key":"guide","kind":"knowledge","id":"b3200000-0000-4000-8000-000000000003"}]')$$,'40001','CONTENT_SOURCE_STALE','unconfigured external source excluded');
select ok(not has_function_privilege('authenticated','public.save_content_version(uuid,uuid,uuid,uuid,integer,jsonb)','EXECUTE'),'no browser generation bypass');
select * from finish();
rollback;
